win32:.clone:
& {
$ErrorActionPreference = 'Stop'
try {
git clone --branch 'main' --single-branch -- 'https://github.com/banodoco/astrid-app' 'C:\Pinokio Apps\O''Malley\Astrid\app\editor'
if ($LASTEXITCODE -ne 0) { throw 'Editor clone failed.' }
} catch {
Write-Output ('ASTRID_PINOKIO_' + 'FAILURE')
throw
}
}

win32:.pull:
& {
$ErrorActionPreference = 'Stop'
try {
$ErrorActionPreference = 'Stop'
$branch = (& git -C 'C:\Pinokio Apps\O''Malley\Astrid\app\editor' branch --show-current).Trim()
if ($LASTEXITCODE -ne 0 -or $branch -ne 'main') { throw 'Editor branch differs from ASTRID_APP_REF. Reset and reinstall to change refs.' }
git -C 'C:\Pinokio Apps\O''Malley\Astrid\app\editor' pull --ff-only
if ($LASTEXITCODE -ne 0) { throw 'Editor update failed.' }
} catch {
Write-Output ('ASTRID_PINOKIO_' + 'FAILURE')
throw
}
}

win32:.install:
& {
$ErrorActionPreference = 'Stop'
try {
$ErrorActionPreference = 'Stop'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$tmp = Join-Path ([IO.Path]::GetTempPath()) ('astrid-pinokio-' + [Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $tmp | Out-Null
try {
  Invoke-WebRequest -UseBasicParsing 'https://astrid.haus/install.ps1' -OutFile (Join-Path $tmp 'install.ps1')
  $global:LASTEXITCODE = 0
  & ([scriptblock]::Create((Get-Content -Raw -LiteralPath (Join-Path $tmp 'install.ps1')))) --root 'C:\Pinokio Apps\O''Malley\Astrid\app\astrid' --managed-by pinokio
  if ($LASTEXITCODE -ne 0) { throw "Astrid installer failed (exit $LASTEXITCODE)." }
} finally { Remove-Item -LiteralPath $tmp -Recurse -Force }
} catch {
Write-Output ('ASTRID_PINOKIO_' + 'FAILURE')
throw
}
}

